<template>
  <div class="api-path-copy-container">
    <div class="api-path-copy" @click="copyPath">
      <span class="api-method">{{ method }}</span>
      <span class="api-path">{{ path }}</span>

      <span v-if="title" class="api-title">({{ title }})</span>

      <span class="api-copy-label">{{ copyLabel }}</span>
    </div>
  </div>
</template>

<script>
export default {
  name: 'CopyPath',
  props: {
    method: String,
    path: String,
    title: String
  },
  computed: {
    copyLabel() {
      return this.$store.state.lang === '繁體中文' ? '複製' : 'Copy'
    },
    copiedText() {
      return this.$store.state.lang === '繁體中文'
          ? '已複製到剪貼簿'
          : 'Copied to clipboard'
    },
    copyValue() {
      return this.path
    }
  },
  methods: {
    async copyPath() {
      try {
        await navigator.clipboard.writeText(this.copyValue)
        this.$message.success(this.copiedText)
      } catch (_) {
        // fallback for older browsers
        const input = document.createElement('input')
        input.value = this.copyValue
        document.body.appendChild(input)
        input.select()
        document.execCommand('copy')
        input.remove()
        this.$message.success(this.copiedText)
      }
    }
  }
}
</script>

<style scoped>
.api-path-copy-container {
  margin: 8px 0 12px;
}

.api-path-copy {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: #303133;
  cursor: pointer;
  flex: 1;
  flex-wrap: nowrap;  /* PC端不換行，保持緊湊 */
  max-width: 100%;
}

/* method 做成小绿標簽，和你截圖風格一致 */
.api-method {
  font-weight: 600;
  font-size: 12px;
  color: #67c23a;
  background: #f0f9eb;
  border-radius: 2px;
  padding: 2px 6px;
  margin-right: 8px;
}

.api-path {
  font-family: Menlo, Monaco, Consolas, monospace;
  word-break: break-all;
  flex: 1;
  min-width: 0;
}

.api-title {
  margin-left: 6px;
  color: #606266;
}

/* 複製按鈕變成小胶囊，PC端緊湊，移動端自適應換行 */
.api-copy-label {
  margin-left: auto;           /* PC端：自動推到最右側 */
  font-size: 12px;
  color: #909399;
  padding: 2px 8px;
  border-radius: 10px;
  border: 1px solid transparent;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.api-path-copy:hover .api-copy-label {
  border-color: #dcdfe6;
  background: #f5f7fa;
  color: #409eff;
}

/* Mobile responsive styles - 移動端才需要換行和特殊間距 */
@media screen and (max-width: 768px) {
  .api-path-copy-container {
    margin: 6px 0 10px;
  }

  .api-path-copy {
    font-size: 11px;
    gap: 4px;
    align-items: flex-start;
    flex-wrap: wrap;  /* 移動端允許換行 */
  }

  .api-method {
    flex-shrink: 0;
    font-size: 11px;
    padding: 1px 4px;
    order: 1;
  }

  .api-path {
    word-break: break-all;
    font-size: 11px;
    flex: 1 1 auto;
    min-width: 0;
    order: 2;
  }

  .api-copy-label {
    flex-shrink: 0;
    font-size: 11px;
    padding: 1px 6px;
    margin-left: 8px;  /* 移動端也緊湊一些 */
    order: 3;
  }

  .api-title {
    font-size: 11px;
    margin-left: 0;
    flex-basis: 100%;
    width: 100%;
    order: 4;
    margin-top: 4px;
  }
}

</style>



