import { codeLangConfig2, CODE_LANG_KEY } from '../lang'

function generateCodeWs(api, codeLang, host, defaultCode) {
  const code = codeLangConfig2.find(item => item.value === codeLang)
  if (!code) {
    return defaultCode || 'No Code'
  }

  const url = window.location.href.toLowerCase();
  // 判斷是否是賬戶信息推送（不需要訂閱channel）
  const isAccountPush = url.indexOf('websocket-賬戶') > -1 || url.indexOf('websocket-account') > -1 || url.indexOf('/account') > -1;

  let codeStr = require("../ws/usdt-m/" + codeLang + '.js').default
  if( api && api.uri)
    codeStr = codeStr.replace(/AAPPII/g, api.uri)

  if (url.indexOf('/spot/') > -1 || url.indexOf('/3-現貨/') > -1 || (url.indexOf('/spot') > -1 && url.indexOf('/cswap') === -1)) {
    codeStr = require("../ws/spot/" + codeLang + '.js').default
    if( api && api.uri)
      codeStr = codeStr.replace(/AAPPII/g, api.uri)
    if (isAccountPush) {
      codeStr = codeStr.replace(/HHOOSSTT/g, "wss://open-api-ws.bingx.com/market?listenKey=YOUR_LISTEN_KEY")
    } else {
     codeStr = codeStr.replace(/HHOOSSTT/g, "wss://open-api-ws.bingx.com/market")
    }
  } else if (url.indexOf('/cswap/') > -1 || url.indexOf('/4-幣本位/') > -1 || url.indexOf('/coin-m') > -1) {
    codeStr = require("../ws/cswap/" + codeLang + '.js').default
    if( api && api.uri)
      codeStr = codeStr.replace(/AAPPII/g, api.uri)
    if (isAccountPush) {
      codeStr = codeStr.replace(/HHOOSSTT/g, "wss://open-api-cswap-ws.bingx.com/market?listenKey=YOUR_LISTEN_KEY")
    } else {
      codeStr = codeStr.replace(/HHOOSSTT/g, "wss://open-api-cswap-ws.bingx.com/market")
    }
  }
  else {
    if (isAccountPush) {
      codeStr = codeStr.replace(/HHOOSSTT/g, "wss://open-api-swap.bingx.com/swap-market?listenKey=YOUR_LISTEN_KEY")
    }else {
      codeStr = codeStr.replace(/HHOOSSTT/g, "wss://open-api-swap.bingx.com/swap-market")
    }
  }

  // 如果是賬戶信息推送，移除訂閱channel的代碼塊
  if (isAccountPush) {
    // 移除標記為訂閱的代碼塊（使用正則匹配多行）
    codeStr = codeStr.replace(/\/\/ SUBSCRIBE_START[\s\S]*?\/\/ SUBSCRIBE_END/g, '');
    codeStr = codeStr.replace(/# SUBSCRIBE_START[\s\S]*?# SUBSCRIBE_END/g, '');
    codeStr = codeStr.replace(/\/\* SUBSCRIBE_START \*\/[\s\S]*?\/\* SUBSCRIBE_END \*\//g, '');
  } else {
    // 如果是行情推送，移除佔位符標記，保留代碼
    codeStr = codeStr.replace(/\/\/ SUBSCRIBE_START\n?/g, '');
    codeStr = codeStr.replace(/\/\/ SUBSCRIBE_END\n?/g, '');
    codeStr = codeStr.replace(/# SUBSCRIBE_START\n?/g, '');
    codeStr = codeStr.replace(/# SUBSCRIBE_END\n?/g, '');
    codeStr = codeStr.replace(/\/\* SUBSCRIBE_START \*\/\n?/g, '');
    codeStr = codeStr.replace(/\/\* SUBSCRIBE_END \*\/\n?/g, '');
  }

  // 對于 Golang，需要將轉義的反引號替換為真正的反引號
  if (codeLang === 'golang') {
    codeStr = codeStr.replace(/\\`/g, '`')
  }

  // PHP 需要先去掉開頭的 "php" 文本
  if (codeLang === 'php') {
    codeStr = codeStr.replace(/^php\s*/, '')
  }



  return codeStr

}

export default generateCodeWs



