import { CODE_LANG_KEY } from '../lang'

function buildUrlParts(api, protocol, host) {
  const payload = api.payload || {}
  const query = Object.keys(payload).map((key, index) => {
    return (index === 0 ? '?' : '&') + encodeURIComponent(key) + '=' + encodeURIComponent(String(payload[key]))
  })
  return [protocol + '://' + host, api.uri].concat(query)
}

function generatePublicCode(api, codeLang, protocol, host, defaultCode) {
  const method = (api.method || 'GET').toUpperCase()
  const urlParts = buildUrlParts(api, protocol, host)
  const parameters = (api.request && api.request.list) || []
  const requiresTimestamp = parameters.some(item => item.name === 'timestamp' && item.required_en === 'Yes')
  if (requiresTimestamp) urlParts.push((Object.keys(api.payload || {}).length ? '&' : '?') + 'timestamp=')
  const literalUrl = (operator, indent) => urlParts.map(part => JSON.stringify(part)).join(` ${operator}\n${indent}`)

  if (codeLang === CODE_LANG_KEY.python) {
    const params = Object.keys(api.payload || {}).map(key => {
      const value = api.payload[key]
      const literal = typeof value === 'number' && Number.isFinite(value) ? String(value) : JSON.stringify(String(value))
      return `        ${JSON.stringify(key)}: ${literal}`
    }).join(',\n')
    return `${requiresTimestamp ? 'import time\n' : ''}import requests

APIURL = ${JSON.stringify(protocol + '://' + host)}


def demo():
    path = ${JSON.stringify(api.uri)}
    method = ${JSON.stringify(method)}
    paramsMap = {${params ? '\n' + params + '\n    ' : ''}}
${requiresTimestamp ? '    paramsMap["timestamp"] = int(time.time() * 1000)\n' : ''}    response = requests.request(method, APIURL + path, params=paramsMap)
    return response.text


if __name__ == '__main__':
    print("demo:", demo())`
  }

  if (codeLang === CODE_LANG_KEY.js) {
    return `// npm install axios -s
import axios from "axios";

async function main() {
    const response = await axios({
        method: ${JSON.stringify(method)},
        url: ${literalUrl('+', '            ')}${requiresTimestamp ? ' + Date.now()' : ''}
    });
    console.log(response.data);
}

main().catch(console.error);`
  }

  if (codeLang === CODE_LANG_KEY.go) {
    return `package main

import (
    "fmt"
    "io"
    "net/http"${requiresTimestamp ? '\n    "time"' : ''}
)

func main() {
    url := ${literalUrl('+', '        ')}${requiresTimestamp ? ' +\n        fmt.Sprint(time.Now().UnixNano() / int64(time.Millisecond))' : ''}
    req, err := http.NewRequest(${JSON.stringify(method)}, url, nil)
    if err != nil {
        panic(err)
    }

    response, err := http.DefaultClient.Do(req)
    if err != nil {
        panic(err)
    }
    defer response.Body.Close()

    body, err := io.ReadAll(response.Body)
    if err != nil {
        panic(err)
    }
    fmt.Println(string(body))
}`
  }

  if (codeLang === CODE_LANG_KEY.java) {
    return `import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class PublicApiDemo {
    public static void main(String[] args) throws Exception {
        URL url = new URL(${literalUrl('+', '                ')}${requiresTimestamp ? ' + System.currentTimeMillis()' : ''});
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod(${JSON.stringify(method)});

        BufferedReader reader = new BufferedReader(
                new InputStreamReader(connection.getInputStream()));
        String line;
        StringBuilder response = new StringBuilder();
        while ((line = reader.readLine()) != null) {
            response.append(line);
        }
        reader.close();
        System.out.println(response);
    }
}`
  }

  if (codeLang === CODE_LANG_KEY.csharp) {
    return `using System;
using System.Net.Http;
using System.Threading.Tasks;

class Program
{
    static async Task Main()
    {
        using (var client = new HttpClient())
        using (var request = new HttpRequestMessage(
            new HttpMethod(${JSON.stringify(method)}),
            ${literalUrl('+', '            ')}${requiresTimestamp ? ' + DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()' : ''}))
        {
            var response = await client.SendAsync(request);
            response.EnsureSuccessStatusCode();
            Console.WriteLine(await response.Content.ReadAsStringAsync());
        }
    }
}`
  }

  if (codeLang === CODE_LANG_KEY.php) {
    return `<?php
$url = ${literalUrl('.', '    ')}${requiresTimestamp ? ' . (string) floor(microtime(true) * 1000)' : ''};
$options = [
    "http" => ["method" => ${JSON.stringify(method)}]
];
$context = stream_context_create($options);
$response = file_get_contents($url, false, $context);
echo $response;`
  }

  if (codeLang === CODE_LANG_KEY.shell) {
    const parts = urlParts.map((part, index) => {
      const value = part + (requiresTimestamp && index === urlParts.length - 1 ? '${TIMESTAMP}' : '')
      return `URL=${JSON.stringify((index === 0 ? '' : '${URL}') + value)}`
    }).join('\n')
    return `${requiresTimestamp ? 'TIMESTAMP=$(date +%s)000\n' : ''}${parts}\n\ncurl --location --request ${JSON.stringify(method)} "$URL"`
  }

  return defaultCode || 'No Code'
}

export default generatePublicCode



