const paths = require.context('./', true, /\.json$/).keys();

export const Data = paths.map(path => {
    const file = require(`${path}`);
    return {
        en: file.en,
        tittle: file.title,
        twoLevel: true,
        docs: [{ doc: file, path: encodeURIComponent(path), pathOri: path }]
    };
});



