const cURL = `
# apt install openssl
# apt install curl

API_KEY=""
API_SECRET=""

TIMESTAMP=$(perl -MTime::HiRes=time -e 'printf("%.0f\\n", time()*1000)')

HOST="HHOOSSTT"
PROTOCOL="PPRROOTTOOCCOOLL"
METHOD="MMEETTHHOODD"
API="AAPPII"

PARAMETERS='PPAARRAAMMEETTEERRSS'

PARAMETERS=$(printf "%s" "$PARAMETERS" | perl -pe 's/(^|&)timestamp=[^&]*//g; s/^&+//; s/&+$//; s/&&+/&/g')

if [ -n "$PARAMETERS" ]; then
  SORTED_LINES=$(printf "%s" "$PARAMETERS" | tr '&' '\\n' | LC_ALL=C sort)
else
  SORTED_LINES=""
fi

if [ -n "$SORTED_LINES" ]; then
  PARAMETERS_SORTED=$(printf "%s" "$SORTED_LINES" | paste -sd '&' -)
  PARAMS_STR="$PARAMETERS_SORTED&timestamp=$TIMESTAMP"
else
  PARAMETERS_SORTED=""
  PARAMS_STR="timestamp=$TIMESTAMP"
fi

sign=$(printf "%s" "$PARAMS_STR" | openssl dgst -sha256 -hmac "$API_SECRET" -hex)
sign=$\{sign##* \}

BODY_PARAMS=""
if [ -n "$PARAMETERS_SORTED" ]; then
  while IFS= read -r part; do
    [ -z "$part" ] && continue
    key=\${part%%=*}
    value=\${part#*=}

    # 判斷 value 類型：數組 / 數字 / 字串
    if printf "%s" "$value" | grep -Eq '^\\[.*\\]$'; then
      json_value="$value"
    elif printf "%s" "$value" | grep -Eq '^-?[0-9]+(\\.[0-9]+)?$'; then
      json_value="$value"
    else
      esc=$(printf "%s" "$value" | sed 's/\\\\/\\\\\\\\/g; s/"/\\\\"/g')
      json_value="\\"$esc\\""
    fi

    if [ -z "$BODY_PARAMS" ]; then
      BODY_PARAMS="\\"$key\\":$json_value"
    else
      BODY_PARAMS="$BODY_PARAMS,\\"$key\\":$json_value"
    fi
  done <<EOF
$SORTED_LINES
EOF
fi

BODY_JSON="{"
if [ -n "$BODY_PARAMS" ]; then
  BODY_JSON="$BODY_JSON$BODY_PARAMS,"
fi
BODY_JSON="$BODY_JSON\\"timestamp\\":$TIMESTAMP,\\"signature\\":\\"$sign\\""
BODY_JSON="$BODY_JSON}"
echo "sign_string: $PARAMS_STR"
echo "body_json: $BODY_JSON"

curl --globoff --location --request "$METHOD" \
  --header "X-BX-APIKEY: $API_KEY" \
  --header "Content-Type: application/json" \
  --data-raw "$BODY_JSON" \
  "$PROTOCOL://$HOST$API"
`
export default cURL




